"""Shared result format. This file is the contract between every part of the pipeline.

Rules every module follows:
  * Every assumption carries exactly one Status. ASSUMED is never a pass and is never
    rendered as one.
  * Modules never raise for bad data; they return a Section with `error` set (plain words).
  * Numbers that cannot be computed are None, never NaN (to_jsonable takes care of it).
  * Modules do NOT edit this file. Anything extra goes into `metrics` / `extra` dicts.
"""
from __future__ import annotations

import math
from dataclasses import asdict, dataclass, field, is_dataclass
from enum import Enum
from typing import Any, Optional

import numpy as np
import pandas as pd


class Status(str, Enum):
    PASS = "tested_ok"          # tested and fine
    CONCERN = "tested_concern"  # tested, with a concern
    FAIL = "failed"             # tested and failed
    ASSUMED = "assumed"         # cannot be (or was not) tested from data -- never a pass

    @staticmethod
    def worst(statuses: list["Status"]) -> Optional["Status"]:
        """Worst *tested* status. ASSUMED is ignored here (it is neither good nor bad);
        use it separately for the assumed panel."""
        order = {Status.PASS: 0, Status.CONCERN: 1, Status.FAIL: 2}
        tested = [s for s in statuses if s in order]
        if not tested:
            return None
        return max(tested, key=lambda s: order[s])


@dataclass
class Assumption:
    key: str                      # stable id, e.g. "no_unmeasured_confounding"
    name: str                     # plain-words name
    status: Status
    detail: str = ""              # plain-words explanation of why this status
    testable: bool = True         # False for things data can never show
    source: str = ""              # which module set it, e.g. "balance", "design.rd"


@dataclass
class Chart:
    """A chart spec the page draws as SVG. `kind` decides the shape of `data`:

    bar      data = {"labels": [str], "values": [float], "ref": float|None, "errors": [float]|None}
    hist     data = {"bins": [float] (edges, len n+1), "series": [{"name": str, "counts": [int]}]}
    scatter  data = {"points": [{"x": float, "y": float, "group": str|None}], "lines": [{"x":[...],"y":[...],"name":str}]}
    line     data = {"series": [{"name": str, "x": [float], "y": [float],
                                 "lo": [float]|None, "hi": [float]|None}], "vline": float|None, "hline": float|None}
    forest   data = {"rows": [{"label": str, "est": float, "lo": float, "hi": float}], "ref": float|None}
    dag      data = {"nodes": [{"id": str, "role": str}],
                     "edges": [{"from": str, "to": str, "type": "directed"|"bidirected"|"undirected"|"partial",
                                "label": str|None, "confidence": float|None}]}
    """
    kind: str
    title: str
    data: dict
    x_label: str = ""
    y_label: str = ""
    note: str = ""


@dataclass
class Section:
    """One card on the page (one check, one design test, the estimate, explore, ...)."""
    key: str
    title: str
    status: Optional[Status] = None      # overall status of the card (None = informational)
    summary: str = ""                    # one or two plain sentences
    metrics: dict = field(default_factory=dict)
    assumptions: list[Assumption] = field(default_factory=list)
    charts: list[Chart] = field(default_factory=list)
    warnings: list[str] = field(default_factory=list)
    caps_verdict: bool = False           # True => verdict cannot be better than Inconclusive
    affects_grade: bool = True           # False for the literature list
    error: Optional[str] = None          # plain-words error; set instead of raising


@dataclass
class ColumnInfo:
    name: str
    kind: str                 # binary | continuous | count | categorical | datetime | id | text | constant
    n_missing: int
    n_unique: int
    encoded_as: list[str]     # names of the columns it became in Prepared.df
    note: str = ""


@dataclass
class Roles:
    treatment: Optional[str] = None
    outcome: Optional[str] = None
    unit: Optional[str] = None
    time: Optional[str] = None
    instrument: Optional[str] = None
    running: Optional[str] = None
    cutoff: Optional[float] = None
    cluster: Optional[str] = None
    strata: Optional[str] = None
    post_treatment: list[str] = field(default_factory=list)   # user-marked (+ suspected) post-treatment columns
    randomized: bool = False                                 # only True if the USER says so
    saturation: Optional[str] = None                         # per-cluster treated-share column, if it was randomized


@dataclass
class Prepared:
    """Output of data.prepare(). `df` is fully numeric (except role columns kept raw).

    df              cleaned frame: all original rows (duplicates kept), booleans as 0/1,
                    covariates imputed (+ `<col>__missing` flags), small categoricals one-hot.
                    Treatment and outcome are NOT imputed. Outcome NaN = missing outcome.
    raw             the uploaded frame, untouched.
    columns         ColumnInfo per original column.
    roles           resolved Roles (original column names; treatment/outcome refer to df columns).
    adjustment_set  THE one adjustment set used by every check and estimator (df column names).
                    Never contains treatment, outcome, roles columns, or post-treatment columns
                    (nor their missing flags / one-hot children).
    notes           plain-words notes about preparation (duplicates, imputation, dropped rows ...).
    """
    df: pd.DataFrame
    raw: pd.DataFrame
    columns: list[ColumnInfo]
    roles: Roles
    adjustment_set: list[str]
    notes: list[str] = field(default_factory=list)
    n_duplicates: int = 0
    encoding: dict = field(default_factory=dict)   # original col -> list of df cols

    # convenience -----------------------------------------------------------------
    @property
    def T(self) -> Optional[pd.Series]:
        return self.df[self.roles.treatment] if self.roles.treatment in self.df else None

    @property
    def Y(self) -> Optional[pd.Series]:
        return self.df[self.roles.outcome] if self.roles.outcome in self.df else None

    def complete(self) -> pd.DataFrame:
        """Rows with observed treatment and outcome."""
        cols = [c for c in [self.roles.treatment, self.roles.outcome] if c]
        return self.df.dropna(subset=cols)

    def treatment_is_binary(self) -> bool:
        t = self.T
        if t is None:
            return False
        vals = set(pd.unique(t.dropna()))
        return vals <= {0, 1} and len(vals) == 2


@dataclass
class Estimand:
    treatment: Optional[str]
    outcome: Optional[str]
    contrast: str = "difference"   # difference | relative | dose_response
    target: str = "ATE"            # ATE | ATT | LATE | local_at_cutoff | dose_response | group_time_ATT
    population: str = "everyone in the data"
    text: str = ""                 # plain-words statement of the estimand


@dataclass
class Claim:
    raw: str
    treatment_phrase: Optional[str] = None
    outcome_phrase: Optional[str] = None
    treatment_col: Optional[str] = None
    outcome_col: Optional[str] = None
    treatment_score: float = 0.0
    outcome_score: float = 0.0
    needs_confirmation: bool = False         # any match score < 0.8
    candidates: dict = field(default_factory=dict)   # role -> [(col, score), ...]
    direction: Optional[str] = None          # increase | decrease | no_effect | nonzero
    negated: bool = False                    # e.g. "does not reduce"
    size: Optional[float] = None             # positive magnitude as written
    size_unit: Optional[str] = None          # percent | pp | absolute | sd | times
    bound: Optional[str] = None              # at_least | at_most | about | exactly
    shape: Optional[str] = None              # linear | threshold | diminishing | nonmonotone | None
    population_phrase: Optional[str] = None
    population_filter: Optional[dict] = None # {"column": str, "op": "==|>=|<=|>|<", "value": Any}
    population_score: float = 0.0
    hedges: list[str] = field(default_factory=list)
    testable: bool = True
    untestable_reason: Optional[str] = None  # mediation | counterfactual | comparison with another treatment
    estimand: Optional[Estimand] = None
    notes: list[str] = field(default_factory=list)


@dataclass
class Estimate:
    method: str                       # plain name e.g. "Two-stage least squares"
    target: str                       # ATE | ATT | LATE | local_at_cutoff | ...
    scope: str = "full"               # full | treated | compliers | local_cutoff | overlap_trimmed
    estimate: Optional[float] = None  # in outcome units (per unit of treatment for continuous T)
    se: Optional[float] = None
    ci90: Optional[tuple] = None
    ci95: Optional[tuple] = None
    p_value: Optional[float] = None
    n: int = 0
    baseline_mean: Optional[float] = None   # control-group (or below-cutoff) outcome mean
    outcome_sd: Optional[float] = None
    refused: bool = False
    refusal_reason: Optional[str] = None
    comparisons: list[dict] = field(default_factory=list)  # other estimators: {"method","estimate","ci95","note"}
    extra: dict = field(default_factory=dict)              # e.g. AR interval, first-stage F, dose curve
    charts: list[Chart] = field(default_factory=list)


@dataclass
class Design:
    kind: str                         # experiment | did | iv | rd | observational
    declared: bool = False
    scores: dict = field(default_factory=dict)   # kind -> score in [0,1] from inference
    ambiguous: bool = False           # two designs fit equally well -> ask the user
    question: Optional[str] = None    # plain-words question when ambiguous
    reasons: list[str] = field(default_factory=list)
    conflicts: list[Assumption] = field(default_factory=list)  # declaration vs data, status FAIL
    assumptions: list[Assumption] = field(default_factory=list)
    grade: Optional[str] = None       # A..F
    grade_reasons: list[str] = field(default_factory=list)


@dataclass
class SubVerdict:
    aspect: str        # direction | size | scope | population | shape | data_quality
    label: str         # supported | rejected | no_evidence | inconclusive | not_claimed | capped | ...
    detail: str = ""


@dataclass
class Verdict:
    label: str                     # Supported | Partly supported | No evidence | Contradicted | Inconclusive | Not testable
    sentence: str                  # one plain sentence
    sub: list[SubVerdict] = field(default_factory=list)
    reasons: list[str] = field(default_factory=list)
    caveat: Optional[str] = None   # e.g. "if no unmeasured confounding"


@dataclass
class Report:
    mode: str                                   # audit | explore
    data: dict = field(default_factory=dict)    # summary of preparation
    claim: Optional[Claim] = None
    design: Optional[Design] = None
    estimand: Optional[Estimand] = None
    sections: list[Section] = field(default_factory=list)
    estimate: Optional[Estimate] = None
    verdict: Optional[Verdict] = None
    assumed_panel: list[Assumption] = field(default_factory=list)
    explore: Optional[Section] = None
    suggestion: Optional[Section] = None
    dag: Optional[Chart] = None
    errors: list[str] = field(default_factory=list)
    needs_input: list[dict] = field(default_factory=list)  # questions for the user (confirm column, pick design)


# ---------------------------------------------------------------------------------
def to_jsonable(obj: Any) -> Any:
    """Convert dataclasses / numpy / pandas / NaN to plain JSON values."""
    if is_dataclass(obj) and not isinstance(obj, type):
        return {k: to_jsonable(v) for k, v in asdict_shallow(obj).items()}
    if isinstance(obj, Enum):
        return obj.value
    if isinstance(obj, dict):
        return {str(k): to_jsonable(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple, set)):
        return [to_jsonable(v) for v in obj]
    if isinstance(obj, (np.integer,)):
        return int(obj)
    if isinstance(obj, (np.floating, float)):
        f = float(obj)
        return None if (math.isnan(f) or math.isinf(f)) else f
    if isinstance(obj, (np.bool_,)):
        return bool(obj)
    if isinstance(obj, np.ndarray):
        return [to_jsonable(v) for v in obj.tolist()]
    if isinstance(obj, (pd.DataFrame, pd.Series)):
        return None  # frames never go to the page
    if isinstance(obj, (pd.Timestamp,)):
        return obj.isoformat()
    return obj


def asdict_shallow(obj) -> dict:
    return {f: getattr(obj, f) for f in obj.__dataclass_fields__}
